package local.hy320.helperstarter;
import android.app.job.*;import android.content.*;import android.os.*;
/** One bounded startup job, never periodic. Boot startup takes precedence over launcher recovery. */
public final class StarterJob extends JobService {
 static final int ID=32034;private StarterRunner runner;private Thread worker;private long generation;private final Handler main=new Handler(Looper.getMainLooper());private Runnable timeout;
 static void schedule(Context context,boolean boot){if(!context.getSharedPreferences("startup",0).getBoolean("enabled",false))return;if(!boot&&context.getSharedPreferences("startup",0).getInt("suspended_boot",-2)==android.provider.Settings.Global.getInt(context.getContentResolver(),"boot_count",-1))return;JobScheduler scheduler=context.getSystemService(JobScheduler.class);JobInfo existing=scheduler.getPendingJob(ID);if(existing!=null&&(existing.getExtras().getBoolean("boot",false)||!boot))return;PersistableBundle extra=new PersistableBundle();extra.putBoolean("boot",boot);JobInfo job=new JobInfo.Builder(ID,new ComponentName(context,StarterJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(1500).setExtras(extra).build();if(scheduler.schedule(job)!=JobScheduler.RESULT_SUCCESS)context.getSharedPreferences("startup",0).edit().putString("last_status","Android deferred automatic startup").apply();}
 @Override public boolean onStartJob(JobParameters parameters){final long token=++generation;final StarterRunner current=new StarterRunner(this);runner=current;final Thread thread=new Thread(()->{try{current.run(parameters.getExtras().getBoolean("boot",false),true);}catch(Exception failure){android.util.Log.w("CYTVStarter","Startup ended: "+failure.getClass().getSimpleName());}finally{main.post(()->{if(generation==token){if(timeout!=null)main.removeCallbacks(timeout);++generation;jobFinished(parameters,false);}});}},"settings-helper-start");worker=thread;timeout=()->{if(generation==token){current.cancel();thread.interrupt();}};main.postDelayed(timeout,45_000);thread.start();return true;}
 @Override public boolean onStopJob(JobParameters parameters){++generation;if(timeout!=null)main.removeCallbacks(timeout);if(runner!=null)runner.cancel();if(worker!=null)worker.interrupt();return false;}
}
